from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # employee -> {year: days_used}
        self._used: dict[str, dict[int, int]] = {}

    def _is_leave_day(self, d: date) -> bool:
        # Weekends (Saturday=5, Sunday=6) are not leave days
        if d.weekday() >= 5:
            return False
        if d in self.holidays:
            return False
        return True

    def _count_days(self, start: date, end: date) -> int:
        total = 0
        current = start
        while current <= end:
            if self._is_leave_day(current):
                total += 1
            current += timedelta(days=1)
        return total

    def _used_for_year(self, employee: str, year: int) -> int:
        return self._used.get(employee, {}).get(year, 0)

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if start > end:
            raise ValueError("Start date must not be after end date.")

        # Requirement 1: must be requested at least 3 days in advance
        if (start - today).days < 3:
            raise ValueError(
                "Leave must be requested at least 3 days before the start date."
            )

        # Count leave days, splitting per calendar year (no carry-over)
        days_per_year: dict[int, int] = {}
        current = start
        while current <= end:
            if self._is_leave_day(current):
                days_per_year[current.year] = days_per_year.get(current.year, 0) + 1
            current += timedelta(days=1)

        total_used = 0
        # Requirement 3 & 4: validate against remaining balance for each year involved
        for year, needed in days_per_year.items():
            remaining = self.days_per_year - self._used_for_year(employee, year)
            if needed > remaining:
                raise ValueError(
                    f"Insufficient leave days for {employee} in {year}: "
                    f"requested {needed}, remaining {remaining}."
                )
            total_used += needed

        # Apply the leave
        emp_usage = self._used.setdefault(employee, {})
        for year, needed in days_per_year.items():
            emp_usage[year] = emp_usage.get(year, 0) + needed

        return total_used

    def remaining(self, employee: str, year: int) -> int:
        return self.days_per_year - self._used_for_year(employee, year)
